// A finding in a Go file whose header says a generator wrote it is marked, wherever the header sits
// before the code, and a file without the header is not, whatever its name.
func TestMarkGeneratedReadsTheGoHeader(t *testing.T) {
	dir := writeTree(t, map[string]string{
		"gen/sizes_gen.go":    "// Code generated by ./gen. DO NOT EDIT.\n\npackage gen\n",
		"gen/after.go":        "// Copyright 2026 The Authors.\n/* a block\n   comment */\n\n// Code generated by stringer. DO NOT EDIT.\npackage gen\n",
		"gen/oneline.go":      "/* license */\n// Code generated by x. DO NOT EDIT.\r\npackage gen\n",
		"gen/late.go":         "package gen\n\n// Code generated by ./gen. DO NOT EDIT.\n",
		"gen/handmade_gen.go": "package gen\n",
		"gen/near.go":         "// Code generated by ./gen; do not edit.\npackage gen\n",
		"main.py":             "# Code generated by ./gen. DO NOT EDIT.\n",
	})
	at := func(uri string) sarif.Result { return sarif.Result{RuleID: "G115", Location: sarif.Location{URI: uri}} }
	results := []sarif.Result{
		at("gen/sizes_gen.go"), at("gen/after.go"), at("gen/oneline.go"), at("gen/late.go"),
		at("gen/handmade_gen.go"), at("gen/near.go"), at("main.py"), at("gen/missing.go"),
		at("../outside.go"), at("file://" + filepath.Join(dir, "gen/sizes_gen.go")), at("gen/sizes_gen.go"),
	}
	markGenerated(dir, results)
	for i, want := range []string{"generated", "generated", "generated", "", "", "", "", "", "", "generated", "generated"} {
		if results[i].Aside != want {
			t.Errorf("%s: aside %q, want %q", results[i].Location.URI, results[i].Aside, want)
		}
	}

	none := []sarif.Result{at("gen/sizes_gen.go")}
	markGenerated("", none)
	if none[0].Aside != "" {
		t.Error("a result with no checkout to read was marked")
	}
}

// A mutable-tag finding is marked pinned only where the lockfile lists that exact reference for
// that same workflow with a commit.
func TestMarkPinnedMatchesTheLockfileExactly(t *testing.T) {
	dir := writeTree(t, map[string]string{
		".github/workflows/ci.yml": "jobs:\n  t:\n    steps:\n" +
			"      - uses: actions/checkout@v7.0.1\n" + // 4
			"        uses: \"actions/setup-go@v7.0.0\" # quoted\n" + // 5
			"      - uses: actions/cache@v5\n" + // 6
			"      - uses: other/action@v1\n" + // 7
			"      - run: echo\n", // 8
		".github/workflows/release.yml":    "      - uses: actions/setup-go@v7.0.0\n",
		".github/actions/setup/action.yml": "      - uses: actions/checkout@v7.0.1\n",
		".github/workflows/actions.lock": "workflows:\n" +
			"    '.github/workflows/ci.yml':\n" +
			"        - 'actions/checkout@v7.0.1'\n" +
			"        - 'actions/setup-go@v7.0.0'\n" +
			"        - 'other/action@v1'\n" +
			"dependencies:\n" +
			"    'actions/checkout@v7.0.1':\n        ref: 'v7.0.1'\n        commit: 'sha1-3d3c42e5aac5ba805825da76410c181273ba90b1'\n" +
			"    'actions/setup-go@v7.0.0':\n        ref: 'v7.0.0'\n        commit: 'sha1-0aaccfd150d50ccaeb58ebd88d36e91967a5f35b'\n" +
			"    'other/action@v1':\n        ref: 'v1'\n",
	})
	const rule = "yaml.github-actions.security.github-actions-mutable-action-tag.github-actions-mutable-action-tag"
	at := func(rule, uri string, line int) sarif.Result {
		return sarif.Result{RuleID: rule, Location: sarif.Location{URI: uri, StartLine: line}}
	}
	results := []sarif.Result{
		at(rule, ".github/workflows/ci.yml", 4),                                               // listed, with a commit
		at(rule, "file://"+filepath.Join(dir, ".github/workflows/ci.yml"), 5),                 // quoted, reported absolute
		at(rule, ".github/workflows/ci.yml", 6),                                               // not listed
		at(rule, ".github/workflows/ci.yml", 7),                                               // listed with no commit
		at(rule, ".github/workflows/ci.yml", 8),                                               // not a uses: line
		at(rule, ".github/workflows/ci.yml", 99),                                              // past the end
		at(rule, ".github/workflows/release.yml", 1),                                          // listed for another workflow
		at(rule, ".github/actions/setup/action.yml", 1),                                       // a composite action
		at("yaml.github-actions.security.run-shell-injection", ".github/workflows/ci.yml", 4), // another rule
	}
	markActions(dir, results)
	for i, want := range []string{"pinned", "pinned", "", "", "", "", "", "", ""} {
		if results[i].Aside != want {
			t.Errorf("result %d (%s:%d): aside %q, want %q", i, results[i].Location.URI, results[i].Location.StartLine, results[i].Aside, want)
		}
	}
	// The reference is recorded on every mutable-tag finding on a uses: line, pinned or not, in a
	// workflow or a composite action.
	for i, want := range []string{"actions/checkout@v7.0.1", "actions/setup-go@v7.0.0", "actions/cache@v5", "other/action@v1",
		"", "", "actions/setup-go@v7.0.0", "actions/checkout@v7.0.1", ""} {
		if results[i].Uses != want {
			t.Errorf("result %d (%s:%d): uses %q, want %q", i, results[i].Location.URI, results[i].Location.StartLine, results[i].Uses, want)
		}
	}
}

// With no lockfile, or one that does not parse, nothing is pinned.
func TestMarkPinnedWithoutAReadableLockfile(t *testing.T) {
	const rule = "github-actions-mutable-action-tag"
	for name, files := range map[string]map[string]string{
		"missing": {".github/workflows/ci.yml": "- uses: a/b@v1\n"},
		"broken":  {".github/workflows/ci.yml": "- uses: a/b@v1\n", ".github/workflows/actions.lock": "workflows: [\n"},
	} {
		dir := writeTree(t, files)
		results := []sarif.Result{{RuleID: rule, Location: sarif.Location{URI: ".github/workflows/ci.yml", StartLine: 1}}}
		markActions(dir, results)
		if results[0].Aside != "" {
			t.Errorf("%s lockfile: marked %q", name, results[0].Aside)
		}
		if results[0].Uses != "a/b@v1" {
			t.Errorf("%s lockfile: uses %q, want the reference read without one", name, results[0].Uses)
		}
	}
	results := []sarif.Result{{RuleID: rule, Location: sarif.Location{URI: ".github/workflows/ci.yml", StartLine: 1}}}
	markActions("", results)
	if results[0].Aside != "" {
		t.Error("a result with no checkout to read was marked")
	}
}

// Both parsers mark what they read: gosec's finding in a generated file, and Semgrep's in a generated
// file and on a pinned action.
func TestTheParsersMarkWhatTheyRead(t *testing.T) {
	sarifDoc := func(tool, rule, uri string, line int) string {
		return `{"version":"2.1.0","runs":[{"tool":{"driver":{"name":"` + tool + `","rules":[{"id":"` + rule +
			`","defaultConfiguration":{"level":"error"}}]}},"results":[{"ruleId":"` + rule +
			`","message":{"text":"m"},"locations":[{"physicalLocation":{"artifactLocation":{"uri":"` + uri +
			`"},"region":{"startLine":` + strconv.Itoa(line) + `}}}]}]}]}`
	}
	dir := writeTree(t, map[string]string{
		"go.mod":                         "module example.com/m\n\ngo 1.26\n",
		"sizes_gen.go":                   "// Code generated by ./gen. DO NOT EDIT.\n\npackage m\n",
		".github/workflows/ci.yml":       "      - uses: actions/checkout@v7.0.1\n",
		".github/workflows/actions.lock": "workflows:\n  '.github/workflows/ci.yml': ['actions/checkout@v7.0.1']\ndependencies:\n  'actions/checkout@v7.0.1': {commit: 'sha1-3d3c'}\n",
	})
	rep, err := parseGosec([]byte(sarifDoc("gosec", "G115", "sizes_gen.go", 3)), dir, nil)
	if err != nil {
		t.Fatal(err)
	}
	if len(rep.Results) != 1 || rep.Results[0].Aside != sarif.AsideGenerated {
		t.Errorf("gosec: %+v", rep.Results)
	}

	const rule = "yaml.github-actions.security.github-actions-mutable-action-tag.github-actions-mutable-action-tag"
	both := `{"version":"2.1.0","runs":[{"tool":{"driver":{"name":"Semgrep OSS","rules":[{"id":"` + rule + `"},{"id":"go.lang.x"}]}},"results":[` +
		`{"ruleId":"` + rule + `","message":{"text":"m"},"locations":[{"physicalLocation":{"artifactLocation":{"uri":".github/workflows/ci.yml"},"region":{"startLine":1}}}]},` +
		`{"ruleId":"go.lang.x","message":{"text":"m"},"locations":[{"physicalLocation":{"artifactLocation":{"uri":"sizes_gen.go"},"region":{"startLine":3}}}]}]}]}`
	rep, err = parseSemgrep(semgrepReportsOf(t, []byte(both), []byte(`{"results":[]}`)), dir, plugin.Config{})
	if err != nil {
		t.Fatal(err)
	}
	got := map[string]string{}
	for _, r := range rep.Results {
		got[r.Location.URI] = r.Aside
	}
	if got[".github/workflows/ci.yml"] != sarif.AsidePinned || got["sizes_gen.go"] != sarif.AsideGenerated {
		t.Errorf("semgrep marks by file = %v", got)
	}
}
